 cloze(E, 'Среда, в которой скорость света меньше, называется оптически более ___.', ['плотной'], 'В ней показатель преломления больше.'),
 ch(E, 'Луч падает на стеклянную пластинку перпендикулярно. Каков угол преломления?', ['0°', '90°', '45°', 'Зависит от стекла'], 0, 'Перпендикулярный луч проходит без преломления.'),
 num(E, 'Во сколько раз скорость света в вакууме больше, чем в веществе с показателем преломления {{n}}?', 'n', 'раз', '$n = c/v$.', [C('n', [1.33, 1.5, 2.42])], decimals=2),
 ch(E, 'Какое явление объясняет радугу?', ['Преломление и дисперсия света в каплях', 'Отражение от облаков', 'Поглощение света', 'Тень от туч'], 0, 'Разные цвета преломляются по-разному.'),
